<?php defined('BASEPATH') or exit('No direct script access allowed');$pdEscape=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$pdPage=$project_discussions;$pdUrl=$url.'?operation_kind=projects&resource_id='.$discussion_project;$pdHidden=function(string $action,array $state,array $extra=[])use($pdEscape,$portal_csrf,$discussion_project){foreach(['action'=>$action,'portal_csrf'=>$portal_csrf,'project_id'=>$discussion_project,'project_revision'=>$state['project_revision'],'discussion_collection_revision'=>$state['collection_revision'],'request_key'=>bin2hex(random_bytes(32))]+$extra as $field=>$value)echo '<input type="hidden" name="'.$pdEscape($field).'" value="'.$pdEscape($value).'">';}; ?>
<section id="portal-project-discussions" style="overflow-wrap:anywhere"><h2>Conversas do projeto</h2><p>Novas conversas e seus comentários ficam privados para você e a equipe. Outros contatos só recebem cada conversa ou comentário após publicação explícita da equipe. Uma resposta da equipe pode ser compartilhada somente com o autor da conversa. Ler e responder a conversas disponíveis não depende da permissão para iniciar uma nova conversa.</p>
<?php if($pdPage['can_open']){echo form_open($url,['id'=>'portal-discussion-open']);$pdHidden('project_discussion_open',$pdPage); ?><label for="portal-discussion-subject">Assunto da nova conversa</label><input style="display:block;width:100%;max-width:100%;box-sizing:border-box" id="portal-discussion-subject" name="discussion_subject" maxlength="191" required><label for="portal-discussion-body">Mensagem privada para a equipe</label><textarea rows="5" style="display:block;width:100%;max-width:100%;box-sizing:border-box" id="portal-discussion-body" name="discussion_body" maxlength="8000" required></textarea><button type="submit">Iniciar conversa privada</button><?= form_close(); ?><?php } ?>
<table id="portal-discussion-list" style="width:100%;table-layout:fixed"><thead><tr><th>Assunto</th><th>Audiência</th><th>Última atividade disponível</th><th>Comentários disponíveis</th></tr></thead><tbody><?php foreach($pdPage['items'] as $item){ ?><tr><td><a href="<?= $pdEscape($pdUrl.'&project_discussion='.$item['id']); ?>"><?= $pdEscape($item['subject']); ?></a></td><td><?= $item['visible']?'Publicada para os contatos autorizados deste cliente':'Privada para você e a equipe'; ?></td><td><?= $pdEscape($item['last_activity']); ?></td><td><?= (int)$item['comment_count']; ?></td></tr><?php } ?></tbody></table>
<?php if($discussion_receipt??null){$pdResult=$discussion_receipt;$pdEvidence=$pdResult['receipt']; ?><article id="portal-discussion-result"><h3>Resultado privado da sua mensagem</h3><p>O registro foi preservado para você e a equipe. Este resultado não publica a mensagem para outros contatos.</p><dl><dt>Autor registrado</dt><dd><?= $pdEscape($pdEvidence['author_name']); ?></dd><dt>Data</dt><dd><?= $pdEscape($pdResult['created_at']); ?></dd><dt>Assunto registrado</dt><dd><?= $pdEscape($pdEvidence['subject']); ?></dd><dt>Registro SHA-256</dt><dd><?= $pdEscape($pdEvidence['source_hash']); ?></dd></dl><p style="white-space:pre-wrap;overflow-wrap:anywhere"><?= $pdEscape($pdEvidence['body']); ?></p><?php if($pdEvidence['kind']==='post'){ ?><a class="portal-discussion-receipt-own-link" href="<?= $pdEscape($pdUrl.'&discussion_parent='.$pdResult['discussion_id'].'&discussion_post='.$pdEvidence['id']); ?>">Retomar meu comentário e anexos</a><?php }if($pdResult['can_open_thread']){ ?><a id="portal-discussion-result-thread" href="<?= $pdEscape($pdUrl.'&project_discussion='.$pdResult['discussion_id']); ?>">Continuar nesta conversa</a><?php }else{ ?><p>A conversa completa não está disponível para seu perfil. Seu próprio resultado permanece acessível por este endereço.</p><?php } ?></article><?php } ?>
<?php if($project_discussion??null){$pdThread=$project_discussion; ?><article id="portal-discussion-detail"><h3><?= $pdEscape($pdThread['subject']); ?></h3><p><?= $pdEscape($pdThread['author_name']); ?> · <?= $pdEscape($pdThread['created_at']); ?> · <?= $pdThread['visible']?'Conversa publicada':'Conversa privada'; ?></p><p style="white-space:pre-wrap;overflow-wrap:anywhere"><?= $pdEscape($pdThread['body']); ?></p><ol id="portal-discussion-posts"><?php foreach($pdThread['posts'] as $post){ ?><li><p><?= $pdEscape($post['author_name']); ?> · <?= $pdEscape($post['created_at']); ?> · <?= $post['audience']==='public'?'Comentário publicado':($post['audience']==='author'?'Compartilhado com o autor da conversa':'Seu comentário privado'); ?></p><p style="white-space:pre-wrap;overflow-wrap:anywhere"><?= $pdEscape($post['body']); ?></p><?php if($post['own']??false){ ?><a class="portal-discussion-own-link" href="<?= $pdEscape($pdUrl.'&discussion_parent='.$pdThread['id'].'&discussion_post='.$post['id']); ?>">Retomar meu comentário e anexos</a><?php } ?></li><?php } ?></ol>
<?php if($pdThread['can_comment']){echo form_open($url,['id'=>'portal-discussion-comment']);$pdHidden('project_discussion_comment',$pdThread,['discussion_id'=>$pdThread['id'],'discussion_revision'=>$pdThread['revision']]); ?><p>Seu comentário ficará privado para você e a equipe até uma publicação explícita. Não envia notificações externas automaticamente.</p><label>Responder a comentário disponível<select name="discussion_reply_to"><option value="">Novo comentário sem resposta vinculada</option><?php foreach($pdThread['posts'] as $replyPost){ ?><option value="<?= (int)$replyPost['id']; ?>">Comentário #<?= (int)$replyPost['id']; ?> · <?= $pdEscape($replyPost['author_name']); ?></option><?php } ?></select></label><label for="portal-discussion-comment-body">Novo comentário</label><textarea rows="5" style="display:block;width:100%;max-width:100%;box-sizing:border-box" id="portal-discussion-comment-body" name="discussion_body" maxlength="8000" required></textarea><button type="submit">Enviar comentário privado</button><?= form_close(); ?><?php }else{ ?><p>A conversa ou o projeto está encerrado para novos comentários.</p><?php } ?></article><?php } ?><?php include __DIR__.'/project_discussion_extras.php'; ?></section>
